async function gh(path){const t=clean(TOKEN);if(!t)throw new Error('нет ключа');if(/[^\x21-\x7e]/.test(t))throw new Error('в ключе лишние символы — вставьте его заново');
const url=`https://api.github.com/repos/${REPO}/contents/${path}?ref=${BRANCH}&_=${Date.now()}`;let r,last;
for(let a=0;a<3;a++){const ctl=new AbortController(),tm=setTimeout(()=>ctl.abort(),90000);
  try{r=await fetch(url,{headers:{Authorization:'Bearer '+t,Accept:'application/vnd.github.raw+json','X-GitHub-Api-Version':'2022-11-28'},cache:'no-store',signal:ctl.signal});
   if(r.status>=500&&a<2){await new Promise(z=>setTimeout(z,1500*(a+1)));continue}
   if(r.ok){const x=await r.text();clearTimeout(tm);return x}break}
  catch(e){last=e;await new Promise(z=>setTimeout(z,1500*(a+1)))}finally{clearTimeout(tm)}}
if(!r)throw new Error(`нет связи с api.github.com (${last&&last.name==='AbortError'?'истекло время':(last&&last.message)||'Load failed'}). Проверьте интернет/VPN и блокировщики контента; файл данных большой — нужна стабильная сеть. Ключ при этом сохранён`);
if(r.status===401)throw new Error('GitHub: ключ не подходит, истёк или отозван (401) — создайте новый');
if(r.status===403)throw new Error(r.headers.get('x-ratelimit-remaining')==='0'?'GitHub: превышен лимит запросов, попробуйте через час':'GitHub: у ключа нет права Contents: Read на '+REPO+' (403)');
if(r.status===404)throw new Error('GitHub: ключ не видит '+REPO+'/'+path+' (404). При создании ключа выберите репозиторий '+REPO+' в «Only select repositories»');
throw new Error('GitHub ответил '+r.status)}
